import { useState } from 'react'
import { AssetIcon } from '../icons'
import { formatClock } from '../utils'

export function TitleCard({
  title,
  inList = false,
  showProgress = false,
  progressSeconds = 0,
  onOpen,
  onPlay,
  onToggleList,
  onRate,
  index = 0,
}) {
  const [hovered, setHovered] = useState(false)
  const durationSeconds = Math.max(1, (title.duration || 45) * 60)
  const progress = showProgress ? Math.min(100, Math.max(2, (progressSeconds / durationSeconds) * 100)) : 0
  const remaining = Math.max(1, Math.round((durationSeconds - progressSeconds) / 60))

  return (
    <article
      className={`title-card ${hovered ? 'hovered' : ''}`}
      style={{ '--card-index': index }}
      tabIndex={0}
      role="button"
      aria-label={`${title.name}, ${title.year}`}
      onClick={() => onOpen?.(title)}
      onKeyDown={(event) => {
        if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault()
          onOpen?.(title)
        }
      }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onFocus={() => setHovered(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setHovered(false)
      }}
    >
      <div className="card-poster-shell">
        <img className="card-poster" src={title.poster} alt="" loading="lazy" />
        {showProgress ? (
          <span className="card-progress" aria-label={`${Math.round(progress)} percent watched`}>
            <span style={{ width: `${progress}%` }} />
          </span>
        ) : null}
        <div className="card-hover-preview">
          <div className="card-preview-image">
            <img src={title.backdrop || title.poster} alt="" loading="lazy" />
            <span className="card-preview-shade" />
            <span className="card-preview-title">{title.name}</span>
          </div>
          <div className="card-preview-body">
            <div className="card-preview-actions">
              <button
                className="round-action play-round"
                aria-label={`Play ${title.name}`}
                onClick={(event) => {
                  event.stopPropagation()
                  onPlay?.(title)
                }}
              >
                <AssetIcon name="play" size={18} />
              </button>
              <button
                className={`round-action ${inList ? 'active' : ''}`}
                aria-label={inList ? `Remove ${title.name} from My List` : `Add ${title.name} to My List`}
                onClick={(event) => {
                  event.stopPropagation()
                  onToggleList?.(title, inList)
                }}
              >
                {inList ? <span className="check-glyph">✓</span> : <AssetIcon name="plus" size={18} />}
              </button>
              <button
                className="round-action"
                aria-label={`Rate ${title.name}`}
                onClick={(event) => {
                  event.stopPropagation()
                  onRate?.(title)
                }}
              >
                <AssetIcon name="thumbs_up" size={18} />
              </button>
              <button
                className="round-action expand-round"
                aria-label={`More information about ${title.name}`}
                onClick={(event) => {
                  event.stopPropagation()
                  onOpen?.(title)
                }}
              >
                <span aria-hidden="true">⌄</span>
              </button>
            </div>
            <div className="card-preview-meta">
              <span className="match-score">{Math.round(72 + (title.rating || 6) * 2)}% Match</span>
              <span className="maturity-inline">{title.maturity_rating}</span>
              <span>{title.year}</span>
              <span className="hd-label">HD</span>
            </div>
            {showProgress ? (
              <p className="preview-progress-copy">{formatClock(progressSeconds)} watched · {remaining}m left</p>
            ) : (
              <div className="preview-tags">
                {(title.genres || []).slice(0, 2).map((genre) => (
                  <span key={genre}>{genre}</span>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
      <p className="card-fallback-title">{title.name}</p>
    </article>
  )
}

export function Top10Card({ title, rank, onOpen }) {
  return (
    <article
      className="top10-card"
      role="button"
      tabIndex={0}
      aria-label={`Number ${rank}: ${title.name}`}
      onClick={() => onOpen?.(title)}
      onKeyDown={(event) => {
        if (event.key === 'Enter' || event.key === ' ') onOpen?.(title)
      }}
    >
      <span className="top10-number" aria-hidden="true">{rank}</span>
      <div className="top10-poster">
        <img src={title.poster} alt="" loading="lazy" />
      </div>
    </article>
  )
}

import { useRef } from 'react'
import { AssetIcon } from '../icons'
import { TitleCard, Top10Card } from './TitleCard'

export function TitleRow({
  title,
  items = [],
  loading = false,
  numbered = false,
  progressRows = false,
  onOpen,
  onPlay,
  onToggleList,
  onRate,
  emptyMessage = 'This collection is empty.',
}) {
  const railRef = useRef(null)

  const scroll = (direction) => {
    const rail = railRef.current
    if (!rail) return
    rail.scrollBy({ left: direction * Math.max(560, rail.clientWidth * 0.82), behavior: 'smooth' })
  }

  return (
    <section className="title-row" aria-labelledby={`row-${title.replace(/\W+/g, '-').toLowerCase()}`}>
      <div className="row-heading">
        <h2 id={`row-${title.replace(/\W+/g, '-').toLowerCase()}`}>{title}</h2>
        {items.length ? <span className="row-count">{items.length}</span> : null}
      </div>
      <div className="row-shell">
        {items.length > 3 ? (
          <button className="row-arrow row-arrow-left" onClick={() => scroll(-1)} aria-label={`Scroll ${title} left`}>
            <AssetIcon name="arrow_left" size={28} />
          </button>
        ) : null}
        <div className={`row-rail ${numbered ? 'numbered-rail' : ''}`} ref={railRef}>
          {loading
            ? Array.from({ length: 6 }).map((_, index) => (
                <div className="skeleton-card" key={index} aria-hidden="true">
                  <span />
                </div>
              ))
            : items.map((item, index) =>
                numbered ? (
                  <Top10Card key={item.id} title={item} rank={item.top10_rank || index + 1} onOpen={onOpen} />
                ) : (
                  <TitleCard
                    key={item.id}
                    title={item}
                    inList={item.in_my_list}
                    showProgress={progressRows}
