const PAGE_TITLES = {
  shows: 'TV Shows',
  movies: 'Movies',
  games: 'Games',
  new: 'New & Popular',
  'my-list': 'My List',
}

function uniqueTitles(items) {
  const seen = new Set()
  return items.filter((item) => {
    if (!item || seen.has(item.id)) return false
    seen.add(item.id)
    return true
  })
}

function sortByRating(items) {
  return [...items].sort((a, b) => Number(b.rating) - Number(a.rating))
}

