import { useState } from 'react'
import { Link, useLocation, useNavigate } from 'react-router-dom'
import { useAuth } from '../AuthContext'
import { Wordmark } from '../icons'

export default function Login() {
  const { login } = useAuth()
  const navigate = useNavigate()
  const location = useLocation()
  const [email, setEmail] = useState(new URLSearchParams(location.search).get('email') || '')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [helpOpen, setHelpOpen] = useState(false)

  const submit = async (event) => {
    event.preventDefault()
    setError('')
    if (!email.trim() || !password) {
      setError('Please enter your email and password.')
      return
    }
    setBusy(true)
    try {
      await login(email.trim(), password)
      navigate('/profiles')
    } catch (requestError) {
      setError(requestError.message || 'Sign in failed. Please try again.')
    } finally {
      setBusy(false)
    }
  }

  const demoLogin = async () => {
    setBusy(true)
    setError('')
    try {
      await login('demo@netflix.com', 'password123')
      navigate('/profiles')
    } catch (requestError) {
      setError(requestError.message || 'The demo account is unavailable.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="auth-page">
      <div className="auth-background" aria-hidden="true">
        <img src="/assets/backdrops/tv_94997.jpg" alt="" />
        <img src="/assets/backdrops/movie_1081003.jpg" alt="" />
        <img src="/assets/backdrops/tv_66732.jpg" alt="" />
        <div className="auth-shade" />
      </div>
      <header className="auth-header">
        <Link to="/" aria-label="Netflix home">
          <Wordmark height={38} />
        </Link>
      </header>
      <main className="auth-main">
        <section className="auth-card" aria-labelledby="sign-in-heading">
          <h1 id="sign-in-heading">Sign In</h1>
          {error ? <div className="auth-error" role="alert">{error}</div> : null}
          <form onSubmit={submit}>
            <label className={`floating-field auth-field ${email ? 'filled' : ''}`}>
              <input
                type="email"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                placeholder=" "
                autoComplete="email"
              />
              <span>Email or mobile number</span>
            </label>
            <label className={`floating-field auth-field ${password ? 'filled' : ''}`}>
              <input
                type="password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                placeholder=" "
                autoComplete="current-password"
              />
              <span>Password</span>
            </label>
            <button className="auth-submit" type="submit" disabled={busy}>
              {busy ? 'Signing In…' : 'Sign In'}
            </button>
          </form>
          <p className="auth-or">OR</p>
          <button className="auth-code-button" type="button" onClick={demoLogin} disabled={busy}>
            Use the demo account
          </button>
          <button className="auth-help-link" type="button" onClick={() => setHelpOpen((value) => !value)}>
            Need help?
          </button>
          {helpOpen ? (
            <div className="auth-help-panel">
              <p>Sign in with the demo account, or create a new account with your email.</p>
              <p className="demo-credentials">demo@netflix.com · password123</p>
            </div>
          ) : null}
          <p className="auth-switch">
            New to Netflix? <Link to="/signup">Sign up now</Link>.
          </p>
          <p className="captcha-note">
            This page is protected by Google reCAPTCHA to ensure you're not a bot.
          </p>
        </section>
      </main>
      <footer className="auth-footer">
        <p>Questions? Call 000-800-919-1694</p>
        <div>
          <Link to="/">Home</Link>
          <Link to="/signup">Sign up</Link>
          <Link to="/login">Sign in</Link>
        </div>
      </footer>
    </div>
  )
}

import { useState } from 'react'
import { Link, useLocation, useNavigate } from 'react-router-dom'
import { useAuth } from '../AuthContext'
import { Wordmark } from '../icons'

export default function Login() {
  const { login } = useAuth()
  const navigate = useNavigate()
  const location = useLocation()
  const [step, setStep] = useState('email')
  const [email, setEmail] = useState(new URLSearchParams(location.search).get('email') || '')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [helpOpen, setHelpOpen] = useState(false)

  const continueWithEmail = (event) => {
    event.preventDefault()
    setError('')
    const value = email.trim()
    if (!value || !value.includes('@')) {
      setError('Please enter a valid email or mobile number.')
      return
    }
    setStep('password')
  }

  const submit = async (event) => {
    event.preventDefault()
    setError('')
    if (!password) {
      setError('Please enter your password.')
      return
    }
    setBusy(true)
    try {
      await login(email.trim(), password)
      navigate('/profiles')
    } catch (requestError) {
      setError(requestError.message || 'Sign in failed. Please try again.')
    } finally {
      setBusy(false)
    }
  }

  const demoLogin = async () => {
    setBusy(true)
    setError('')
    try {
      await login('demo@netflix.com', 'password123')
      navigate('/profiles')
    } catch (requestError) {
      setError(requestError.message || 'The demo account is unavailable.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="signin-page">
      <header className="signin-header">
        <Link to="/" aria-label="Netflix home">
          <Wordmark height={36} />
        </Link>
      </header>
      <main className="signin-main">
        <section className="signin-panel">
          <h1>{step === 'email' ? 'Enter your info to sign in' : 'Enter your password'}</h1>
          <p className="signin-subtitle">
            {step === 'email' ? (
              <>Or <Link to="/signup">get started with a new account</Link>.</>
            ) : (
              <>Signing in as <strong>{email}</strong>. <button type="button" onClick={() => setStep('email')}>Change</button></>
            )}
          </p>
          {error ? <div className="signin-error" role="alert">{error}</div> : null}
          {step === 'email' ? (
            <form onSubmit={continueWithEmail}>
              <label className={`signin-field ${email ? 'filled' : ''}`}>
                <input
                  type="email"
                  value={email}
                  onChange={(event) => { setEmail(event.target.value); setError('') }}
                  placeholder=" "
                  autoComplete="email"
                  autoFocus
                />
                <span>Email or mobile number</span>
              </label>
              <button className="signin-continue" type="submit">Continue</button>
            </form>
          ) : (
            <form onSubmit={submit}>
              <label className={`signin-field ${password ? 'filled' : ''}`}>
                <input
                  type="password"
                  value={password}
                  onChange={(event) => { setPassword(event.target.value); setError('') }}
                  placeholder=" "
                  autoComplete="current-password"
                  autoFocus
                />
                <span>Password</span>
              </label>
              <button className="signin-continue" type="submit" disabled={busy}>
                {busy ? 'Signing In…' : 'Sign In'}
              </button>
            </form>
          )}
          <button className="signin-get-help" type="button" onClick={() => setHelpOpen((value) => !value)}>
            Get Help
          </button>
          {helpOpen ? (
            <div className="signin-help-panel">
              <p>Use the demo account below, or create a new Netflix account.</p>
              <p className="demo-credentials">demo@netflix.com · password123</p>
              <button type="button" onClick={demoLogin} disabled={busy}>Sign in with the demo account</button>
            </div>
          ) : null}
          {step === 'email' ? (
            <button className="signin-demo-link" type="button" onClick={demoLogin} disabled={busy}>
              Use the demo account
            </button>
          ) : null}
          <p className="signin-captcha">This page is protected by Google reCAPTCHA to ensure you're not a bot.</p>
        </section>
      </main>
      <footer className="signin-footer">
        <p>Questions? Call 1-844-569-7700 (Toll-Free)</p>
        <div>
          <Link to="/">FAQ</Link>
          <Link to="/login?help=1">Help Centre</Link>
          <Link to="/browse">Netflix House</Link>
          <Link to="/signup">Netflix Shop</Link>
          <Link to="/login">Terms of Use</Link>
          <Link to="/login">Privacy</Link>
          <Link to="/login">Cookie Preferences</Link>
          <Link to="/signup">Corporate Information</Link>
        </div>
      </footer>
    </div>
  )
}

